{
	"name": "@ichisay/opencode-agy-plugin",
	"version": "0.5.1",
	"type": "module",
	"main": "./dist/index.js",
	"license": "MIT",
	"description": "OpenCode plugin + provider that routes LLM prompts to agy (Google Antigravity CLI)",
	"author": "ichisay",
	"keywords": ["opencode", "opencode-plugin", "agy", "antigravity", "provider"],
	"engines": {
		"node": ">=18"
	},
	"publishConfig": {
		"access": "public",
		"registry": "https://registry.npmjs.org/"
	},
	"exports": {
		".": "./dist/index.js",
		"./provider": "./dist/provider.js",
		"./plugin": "./dist/plugin.js"
	},
	"files": [
		"dist",
		"plugin.js",
		"provider.js",
		"README.md",
		"LICENSE",
		"docs/README_ja.md",
		"docs/README_ko.md",
		"docs/README_zh.md"
	],
	"scripts": {
		"prepack": "bun run build",
		"build": "bun run build:clean && bun run build:types && bun run build:bundle",
		"build:clean": "node -e \"const fs=require('node:fs'),p='dist';fs.mkdirSync(p,{recursive:true});for(const entry of fs.readdirSync(p))fs.rmSync(p+'/'+entry,{recursive:true,force:true})\"",
		"build:types": "tsc --emitDeclarationOnly --declaration",
		"build:bundle": "bun build ./src/index.ts ./src/plugin.ts ./src/provider.ts --outdir ./dist --target node --format esm",
		"test": "bun test",
		"test:e2e": "bun run test:e2e:mock",
		"test:e2e:mock": "bun run build && bun tests/e2e/opencode.ts",
		"test:e2e:real": "bun tests/smoke.ts"
	},
	"peerDependencies": {
		"@ai-sdk/provider": "^3.0.0"
	},
	"peerDependenciesMeta": {
		"@ai-sdk/provider": {
			"optional": true
		}
	},
	"devDependencies": {
		"@ai-sdk/provider": "^3.0.0",
		"@opencode-ai/plugin": "1.18.18",
		"@opencode-ai/sdk": "1.18.18",
		"@types/bun": "latest",
		"opencode-ai": "1.18.18",
		"typescript": "^5.8.0"
	},
	"dependencies": {
		"@ai-sdk/openai": "^3.0.67",
		"zod": "^3.25.0-beta.20250519T094321"
	}
}
